377	    /** Whether the person clashes: their name or an alias is used as a name or alias on another
378	     *  sheet of their sheet's tree (see {@link SheetService#tree}). */
379	    @Transactional(readOnly = true)
380	    public boolean clashing(String sheetId, Person person) {
381	        return clashing(sheetId).test(person);
382	    }
383	
384	    /** A test of whether a person on the sheet clashes, reading the sheet's tree once. */
385	    @Transactional(readOnly = true)
386	    public Predicate<Person> clashing(String sheetId) {
387	        Set<String> tree = treeNames(sheetId);
388	        if (tree.isEmpty()) {
389	            return p -> false;
390	        }
391	        return p -> inTree(tree, p.getName()) || p.getAliases().stream().anyMatch(a -> inTree(tree, a));
392	    }
393	
394	    /** The names and aliases used on the other sheets of the sheet's tree, lower-cased. */
395	    private Set<String> treeNames(String sheetId) {
396	        Set<String> tree = sheets.tree(sheetId);
397	        if (tree.isEmpty()) {
398	            return Set.of();
399	        }
400	        Set<String> names = new HashSet<>(people.namesOn(tree));
401	        names.addAll(people.aliasesOn(tree));
402	        return names;
403	    }
404	
405	    private static boolean inTree(Set<String> treeNames, String name) {
406	        return treeNames.contains(name.toLowerCase(Locale.ROOT));
407	    }
408	
409	    /** Retire a person from a day; a day left out takes the sheet's today. */
410	    @Transactional
411	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
412	        Person person = people.findByIdAndSheetId(personId, sheetId)
413	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
414	        LocalDate on = from != null ? from : sheets.today(sheetId);
415	        return rollup.tracking(sheetId, user, () -> {
416	            person.setRetiredFrom(on);
417	            Person saved = saveUnique(person);
418	            audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
419	                    + " from=" + on);
420	            return saved;
421	        });
422	    }
423	
424	    /** Put a person on hold from a day (null: the sheet's today) to a day (null: open-ended),
425	     *  keeping their other holds; refused when the to-date is before the from-date. */
426	    @Transactional
427	    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
428	        Person person = people.findByIdAndSheetId(personId, sheetId)
429	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
430	        LocalDate on = from != null ? from : sheets.today(sheetId);
431	        if (to != null && to.isBefore(on)) {
432	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts");
433	        }
434	        return rollup.tracking(sheetId, user, () -> {
435	            person.addHold(on, to);
436	            Person saved = saveUnique(person);
437	            audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
438	                    + " from=" + on);
439	            return saved;
440	        });
441	    }
442	
443	    /** A record of the person with the grade in force on the sheet's today. */
444	    private static String record(String event, String sheetId, String user, Person person, LocalDate today) {
445	        return event + " sheet=" + sheetId + " by=" + user + " name=" + person.getName() + " grade="
446	                + person.gradeOn(today);
447	    }
448	
449	    /** Save, refusing a name or contact another user took on the sheet in the meantime, or a person
450	     *  another user saved in the meantime. */
451	    private Person saveUnique(Person person) {
452	        try {
453	            return people.saveAndFlush(person);
454	        } catch (DataIntegrityViolationException e) {
455	            String constraint = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(Locale.ROOT);
456	            throw constraint.contains("PERSON_SHEET_CONTACT_UNIQUE") ? contactInUse() : nameInUse();
457	        } catch (OptimisticLockingFailureException e) {
458	            throw changedMeanwhile();
459	        }
460	    }
461	
462	    private static ResponseStatusException changedMeanwhile() {
463	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
464	                "Someone else saved this person in the meantime");
465	    }
466	
467	    private static ResponseStatusException contactInUse() {
468	        return new ResponseStatusException(HttpStatus.CONFLICT, "That contact is already held on this sheet");
469	    }
470	
471	    private static ResponseStatusException nameInUse() {
472	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet");
473	    }
474	}
